use vstd::prelude::*;

verus! {
    /// Given a three‐digit integer n in [100,999], produce a Vec<char> of length 6
    /// whose first three entries are 'A','B','C', and whose last three entries
    /// are the decimal digits of n in order.
    fn solve(n: i8) -> (result: Vec<char>)
        requires
            100 <= n && n <= 999,
        ensures
            result.len() == 6,
            // header
            result[0] == 'A',
            result[1] == 'B',
            result[2] == 'C',
            // decimal digits
            result[3] == ((b'0' + (n / 100) as u8) as char),
            result[4] == ((b'0' + ((n / 10) % 10) as u8) as char),
            result[5] == ((b'0' + (n % 10) as u8) as char),
    {
        let mut res: Vec<char> = Vec::new();
        // push the fixed prefix
        res.push('A');
        assert(res.len() == 1);
        res.push('B');
        assert(res.len() == 2);
        res.push('C');
        assert(res.len() == 3);

        // compute and push the hundreds digit
        let hund: u8 = (n / 100) as u8;
        let ch0: char = (b'0' + hund) as char;
        res.push(ch0);
        assert(res.len() == 4);

        // compute and push the tens digit
        let tens: u8 = ((n / 10) % 10) as u8;
        let ch1: char = (b'0' + tens) as char;
        res.push(ch1);
        assert(res.len() == 5);

        // compute and push the units digit
        let unit: u8 = (n % 10) as u8;
        let ch2: char = (b'0' + unit) as char;
        res.push(ch2);
        assert(res.len() == 6);

        // return
        res
    }
}

fn main() {
    // example
    let v = solve(372);
    // should be ['A','B','C','3','7','2']
    assert!(v == vec!['A','B','C','3','7','2']);
}